UPDATE USL lightning.metastore.registry_audit.stage_audit.tumour_case SET TABLE DESCRIPTION One tumour case from the cancer registry, keyed by the case submitter id;
UPDATE USL lightning.metastore.registry_audit.stage_audit.tumour_case.case_id SET COLUMN DESCRIPTION GDC case submitter id and the primary key of the case;
UPDATE USL lightning.metastore.registry_audit.stage_audit.tumour_case.primary_site SET COLUMN DESCRIPTION Anatomical site recorded for the case;
UPDATE USL lightning.metastore.registry_audit.stage_audit.tumour_case.site_key SET COLUMN DESCRIPTION Site family used to match staging rules, such as breast or colon;
UPDATE USL lightning.metastore.registry_audit.stage_audit.tumour_case.year_of_diagnosis SET COLUMN DESCRIPTION Year the diagnosis was recorded;
UPDATE USL lightning.metastore.registry_audit.stage_audit.path_report SET TABLE DESCRIPTION One pathology report linked to a tumour case;
UPDATE USL lightning.metastore.registry_audit.stage_audit.path_report.report_id SET COLUMN DESCRIPTION Identifier of the pathology report;
UPDATE USL lightning.metastore.registry_audit.stage_audit.path_report.case_id SET COLUMN DESCRIPTION Tumour case this report belongs to;
UPDATE USL lightning.metastore.registry_audit.stage_audit.path_report.report_text SET COLUMN DESCRIPTION Full text of the pathology report;
UPDATE USL lightning.metastore.registry_audit.stage_audit.recorded_stage SET TABLE DESCRIPTION Pathologic stage values recorded for the case in the registry;
UPDATE USL lightning.metastore.registry_audit.stage_audit.recorded_stage.case_id SET COLUMN DESCRIPTION Tumour case these recorded stage values belong to;
UPDATE USL lightning.metastore.registry_audit.stage_audit.recorded_stage.site_key SET COLUMN DESCRIPTION Site family used to choose staging rules for this case;
UPDATE USL lightning.metastore.registry_audit.stage_audit.recorded_stage.pathologic_t SET COLUMN DESCRIPTION Registry T category with a leading p or yp removed and letters uppercased;
UPDATE USL lightning.metastore.registry_audit.stage_audit.recorded_stage.pathologic_n SET COLUMN DESCRIPTION Registry N category with a leading p or yp removed and letters uppercased (audited: where this field and the other node field cannot both be true, stage_check.fault_field names the field the report contradicts);
UPDATE USL lightning.metastore.registry_audit.stage_audit.recorded_stage.pathologic_stage SET COLUMN DESCRIPTION Registry stage group as recorded;
UPDATE USL lightning.metastore.registry_audit.stage_audit.recorded_stage.edition SET COLUMN DESCRIPTION Staging system edition as recorded;
UPDATE USL lightning.metastore.registry_audit.stage_audit.recorded_stage.edition_code SET COLUMN DESCRIPTION Edition number taken from the recorded edition, such as 6, 7, or 8;
UPDATE USL lightning.metastore.registry_audit.stage_audit.recorded_stage.lymph_nodes_positive SET COLUMN DESCRIPTION Number of positive regional lymph nodes recorded for the case (audited: where this field and the other node field cannot both be true, stage_check.fault_field names the field the report contradicts);
UPDATE USL lightning.metastore.registry_audit.stage_audit.recorded_stage.lymph_nodes_tested SET COLUMN DESCRIPTION Number of regional lymph nodes examined for the case;
UPDATE USL lightning.metastore.registry_audit.stage_audit.recorded_stage.year_of_diagnosis SET COLUMN DESCRIPTION Year of the diagnosis row chosen for this case;
UPDATE USL lightning.metastore.registry_audit.stage_audit.recorded_stage.n_main SET COLUMN DESCRIPTION Main N category of the recorded N value, such as N0 or N1, with the subcategory removed;
UPDATE USL lightning.metastore.registry_audit.stage_audit.staging_rule SET TABLE DESCRIPTION One paraphrased staging rule used to derive or check a T or N category;
UPDATE USL lightning.metastore.registry_audit.stage_audit.staging_rule.rule_id SET COLUMN DESCRIPTION Stable identifier of the staging rule;
UPDATE USL lightning.metastore.registry_audit.stage_audit.staging_rule.site SET COLUMN DESCRIPTION Site family the rule applies to;
UPDATE USL lightning.metastore.registry_audit.stage_audit.staging_rule.element SET COLUMN DESCRIPTION T or N, the stage element the rule assigns;
UPDATE USL lightning.metastore.registry_audit.stage_audit.staging_rule.edition SET COLUMN DESCRIPTION Comma-separated edition numbers the rule applies to;
UPDATE USL lightning.metastore.registry_audit.stage_audit.staging_rule.condition_text SET COLUMN DESCRIPTION Our paraphrase of when the rule applies;
UPDATE USL lightning.metastore.registry_audit.stage_audit.staging_rule.min_value SET COLUMN DESCRIPTION Inclusive lower bound for a numeric rule, in millimetres for size or a node count;
UPDATE USL lightning.metastore.registry_audit.stage_audit.staging_rule.max_value SET COLUMN DESCRIPTION Inclusive upper bound for a numeric rule, in millimetres for size or a node count;
UPDATE USL lightning.metastore.registry_audit.stage_audit.staging_rule.output SET COLUMN DESCRIPTION Category the rule assigns, or a review marker when it does not assign one;
UPDATE USL lightning.metastore.registry_audit.stage_audit.staging_rule.cite SET COLUMN DESCRIPTION Public source codes for the paraphrase;
UPDATE USL lightning.metastore.registry_audit.stage_audit.derived_stage SET TABLE DESCRIPTION A derived T or N value, from the node-count rules or from a report extraction;
UPDATE USL lightning.metastore.registry_audit.stage_audit.derived_stage.case_id SET COLUMN DESCRIPTION Tumour case this derived value belongs to;
UPDATE USL lightning.metastore.registry_audit.stage_audit.derived_stage.method SET COLUMN DESCRIPTION How the value was produced. sql_node_count is the node-count rule. Other methods are model extractions;
UPDATE USL lightning.metastore.registry_audit.stage_audit.derived_stage.field SET COLUMN DESCRIPTION Stage element, T or N;
UPDATE USL lightning.metastore.registry_audit.stage_audit.derived_stage.value SET COLUMN DESCRIPTION Derived category;
UPDATE USL lightning.metastore.registry_audit.stage_audit.derived_stage.quote SET COLUMN DESCRIPTION Verbatim source span supporting a model extraction;
UPDATE USL lightning.metastore.registry_audit.stage_audit.derived_stage.quote_start SET COLUMN DESCRIPTION Start offset of the quote in the report text;
UPDATE USL lightning.metastore.registry_audit.stage_audit.derived_stage.quote_end SET COLUMN DESCRIPTION End offset of the quote in the report text;
UPDATE USL lightning.metastore.registry_audit.stage_audit.derived_stage.model SET COLUMN DESCRIPTION Model id that produced a model extraction;
UPDATE USL lightning.metastore.registry_audit.stage_audit.derived_stage.receipt_id SET COLUMN DESCRIPTION Provider receipt id for a model extraction;
UPDATE USL lightning.metastore.registry_audit.stage_audit.derived_stage.created_at SET COLUMN DESCRIPTION When the derived value was recorded;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check SET TABLE DESCRIPTION Recorded stage and derived stage for one case, side by side, for the data-quality checks;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.case_id SET COLUMN DESCRIPTION Tumour case this comparison belongs to;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.site_key SET COLUMN DESCRIPTION Site family used to choose the node-count rule;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.edition_code SET COLUMN DESCRIPTION Edition number the checks use;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.recorded_t SET COLUMN DESCRIPTION Registry T category normalised the same way as a report extraction;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.recorded_n SET COLUMN DESCRIPTION Registry N category normalised the same way as a report extraction (audited: where this field and the other node field cannot both be true, stage_check.fault_field names the field the report contradicts);
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.recorded_stage SET COLUMN DESCRIPTION Registry stage group as recorded;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.recorded_n_main SET COLUMN DESCRIPTION Main N category recorded for the case;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.lymph_nodes_positive SET COLUMN DESCRIPTION Positive regional nodes used to choose the N rule (audited: where this field and the other node field cannot both be true, stage_check.fault_field names the field the report contradicts);
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.lymph_nodes_tested SET COLUMN DESCRIPTION Examined regional nodes. A zero or missing count selects the not-examined rule;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.derived_n SET COLUMN DESCRIPTION N category chosen from the staging rules using the positive-node count;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.derived_n_main SET COLUMN DESCRIPTION Main N category of that rule output;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.report_t SET COLUMN DESCRIPTION Model-derived T category when a report extraction exists, normalised. If several exist, the greatest value is shown;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.report_n SET COLUMN DESCRIPTION Model-derived N category when a report extraction exists, normalised. If several exist, the greatest value is shown;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.year_of_diagnosis SET COLUMN DESCRIPTION Year the tumour was diagnosed, from the case record;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.edition_year_class SET COLUMN DESCRIPTION Whether the staging edition was in use in the diagnosis year (with one year of transition slack): in_window, out_of_window or unknown;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.reason_class SET COLUMN DESCRIPTION How the recorded N and the node count relate: n_count_contradiction, n_missing_derivable, n_ambiguous_micromet, count_missing, or consistent;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.report_n_main SET COLUMN DESCRIPTION Main N category the pathology report supports, from a quote-verified model extraction;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.report_nodes_positive SET COLUMN DESCRIPTION Positive regional nodes stated in the report, accepted only when the number lies inside its verified quote;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.fault_field SET COLUMN DESCRIPTION For a node-count contradiction or a missing N, the registry field the quote-verified report evidence points to: node_count (needs a verified report count that differs from the registry count), pathologic_n, or review when the evidence does not settle it;
UPDATE USL lightning.metastore.registry_audit.stage_audit.stage_check.positive_nodes_checked SET COLUMN DESCRIPTION Positive regional node count after the report check, as a whole number: the registry count, except where fault_field is node_count, where the quote-verified report count replaces it, and empty where fault_field is review or no count is recorded;
UPDATE USL lightning.metastore.registry_audit.stage_audit.parse_block SET TABLE DESCRIPTION One text block that Nemotron Parse read on a page of the original scanned pathology report, with its box;
UPDATE USL lightning.metastore.registry_audit.stage_audit.parse_block.case_id SET COLUMN DESCRIPTION Tumour case the scanned report belongs to;
UPDATE USL lightning.metastore.registry_audit.stage_audit.parse_block.page_no SET COLUMN DESCRIPTION Page of the report PDF, counting from 0;
UPDATE USL lightning.metastore.registry_audit.stage_audit.parse_block.block_index SET COLUMN DESCRIPTION Position of the block in Nemotron Parse reading order on that page;
UPDATE USL lightning.metastore.registry_audit.stage_audit.parse_block.block_text SET COLUMN DESCRIPTION Text Nemotron Parse read inside the box;
UPDATE USL lightning.metastore.registry_audit.stage_audit.parse_block.block_kind SET COLUMN DESCRIPTION Layout class Nemotron Parse gave the block, such as Text, Table or Caption;
UPDATE USL lightning.metastore.registry_audit.stage_audit.parse_block.xmin SET COLUMN DESCRIPTION Left edge of the box as a fraction of the 1024 by 1280 page canvas;
UPDATE USL lightning.metastore.registry_audit.stage_audit.parse_block.ymin SET COLUMN DESCRIPTION Top edge of the box as a fraction of the page canvas;
UPDATE USL lightning.metastore.registry_audit.stage_audit.parse_block.xmax SET COLUMN DESCRIPTION Right edge of the box as a fraction of the page canvas;
UPDATE USL lightning.metastore.registry_audit.stage_audit.parse_block.ymax SET COLUMN DESCRIPTION Bottom edge of the box as a fraction of the page canvas;
UPDATE USL lightning.metastore.registry_audit.stage_audit.parse_block.model SET COLUMN DESCRIPTION Model that read the page, as served;
UPDATE USL lightning.metastore.registry_audit.stage_audit.parse_block.gdc_file_id SET COLUMN DESCRIPTION Open-access GDC file id of the scanned report;
UPDATE USL lightning.metastore.registry_audit.stage_audit.flag SET TABLE DESCRIPTION One review-queue flag raised for a case;
UPDATE USL lightning.metastore.registry_audit.stage_audit.flag.flag_id SET COLUMN DESCRIPTION Unique identifier of the flag;
UPDATE USL lightning.metastore.registry_audit.stage_audit.flag.case_id SET COLUMN DESCRIPTION Tumour case this flag belongs to;
UPDATE USL lightning.metastore.registry_audit.stage_audit.flag.rule_id SET COLUMN DESCRIPTION Rule that raised the flag;
UPDATE USL lightning.metastore.registry_audit.stage_audit.flag.field SET COLUMN DESCRIPTION Stage field the flag is about;
UPDATE USL lightning.metastore.registry_audit.stage_audit.flag.recorded_value SET COLUMN DESCRIPTION Value recorded in the registry;
UPDATE USL lightning.metastore.registry_audit.stage_audit.flag.derived_value SET COLUMN DESCRIPTION Value the check derived;
UPDATE USL lightning.metastore.registry_audit.stage_audit.flag.quote SET COLUMN DESCRIPTION Verbatim source span that supports the flag;
UPDATE USL lightning.metastore.registry_audit.stage_audit.flag.reason SET COLUMN DESCRIPTION Why the row was sent to review;
UPDATE USL lightning.metastore.registry_audit.stage_audit.flag.severity SET COLUMN DESCRIPTION How serious the disagreement is;
UPDATE USL lightning.metastore.registry_audit.stage_audit.flag.model SET COLUMN DESCRIPTION Model id recorded with the flag;
UPDATE USL lightning.metastore.registry_audit.stage_audit.flag.receipt_id SET COLUMN DESCRIPTION Provider receipt id recorded with the flag;
UPDATE USL lightning.metastore.registry_audit.stage_audit.flag.created_at SET COLUMN DESCRIPTION When the flag was recorded;
